INSERT INTO `bulletin_posts` (`id`, `title`, `content`, `excerpt`, `featured_image`, `category_id`, `author_id`, `barangay_id`, `status`, `visibility`, `is_featured`, `is_urgent`, `view_count`, `published_at`, `created_at`, `updated_at`) VALUES
(1, '9th Regular Session of the Sangguniang Kabataan (SK) Pederasyon of Iriga City', 'The 9th Regular Session of the Sangguniang Kabataan (SK) Pederasyon of Iriga City served as a formal assembly of SK Federation officers and representatives from the different barangays of the city. The session aimed to discuss and deliberate on youth-related programs, policies, and resolutions that promote active participation, leadership, and development among the youth sector. Key agenda items included updates on ongoing projects, budget utilization reports, approval of upcoming youth activities, and coordination plans with the Panlungsod na Pederasyon office.', NULL, '1762415511_be58d0a8c63e84a7bfc4.jpg', NULL, 1, NULL, 'published', 'city', 1, 0, 3, '2025-11-06 15:51:51', '2025-11-06 15:51:51', '2025-11-28 10:26:03'),
(2, 'Search for Iriga City Youth Officials', 'The Search for Iriga City Youth Officials is a youth development initiative that aims to empower young Irigueños by providing them with a platform to experience leadership and public service firsthand. The program selects outstanding youth representatives who will serve as counterparts to the city’s key government officials, allowing them to participate in governance, decision-making, and community service activities.', NULL, '1762415580_1075f6d67d4f40e2e679.jpg', NULL, 1, NULL, 'published', 'city', 1, 0, 3, '2025-11-06 15:53:00', '2025-11-06 15:53:00', '2025-11-28 10:26:03'),
(3, 'Arbor Day Tree Planting Activity 2025', 'The Arbor Day Tree Planting Activity 2025 is an environmental initiative spearheaded by the Sangguniang Kabataan (SK) Pederasyon of Iriga City in collaboration with local government offices and community volunteers. The activity aims to promote environmental awareness, sustainability, and climate action through the planting of trees in designated areas across the city.', NULL, '1762415628_8d57e53b77ae4f10cf66.jpg', NULL, 1, NULL, 'published', 'city', 1, 0, 10, '2025-11-06 15:53:48', '2025-11-06 15:53:48', '2026-01-30 11:40:11');
