INSERT INTO `documents` (`id`, `filename`, `title`, `filepath`, `uploaded_by`, `uploaded_at`, `filesize`, `mimetype`, `visibility`, `barangay_id`, `visibility_scope`, `thumbnail_path`, `description`, `tags`, `downloadable`) VALUES
(1, 'SAMPLE', NULL, 'uploads/documents/1762420120_8ffbcadee6023b8e66e0.pdf', 'SK_DessaMareLontayao', '2025-11-06 17:08:40', 152187, 'application/pdf', 'SK', NULL, 'all', 'uploads/thumbnails/1762420120_8ffbcadee6023b8e66e0.jpg', 'sample sample', '', 1);
INSERT INTO `event` (`event_id`, `barangay_id`, `google_event_id`, `title`, `description`, `status`, `publish_date`, `start_datetime`, `end_datetime`, `location`, `target_participants`, `event_banner`, `category`, `created_by`, `created_at`, `updated_at`, `scheduling_enabled`, `scheduled_publish_datetime`, `sms_notification_enabled`, `sms_recipient_scope`, `sms_recipient_barangays`, `sms_recipient_roles`) VALUES
(2, 1, 'nel555fqabs12qm2dhosn94khs', 'Barangay at Katipunan ng Kabataan Assembly', '“Tinig ng Kabataan, Dinig ng Barangay!” Sama-sama nating pag-usapan ang kinabukasan ng ating barangay at kabataan sa Barangay at KK Assembly. Layunin ng pagtitipon na hikayatin ang mga kabataan at mamamayan na makibahagi sa mga usaping pangkomunidad, magbahagi ng kanilang opinyon, at magmungkahi ng mga proyektong makatutulong sa pag-unlad ng barangay. Maging bahagi ng pagkilos at pagbabago para sa mas maunlad at nagkakaisang komunidad!', 'Published', '2025-11-06 01:05:19', '2025-10-22 08:00:00', '2025-10-22 11:59:00', 'Antipolo Barangay Chapel, Iriga City', 70, '1762362319_b05b2a58068e2b303923.jpg', 'active citizenship', 25, '2025-11-05 09:05:19', '2025-11-05 09:05:21', 0, NULL, 0, NULL, NULL, NULL),
(3, 16, 'mr1rpdq3vnm8ttgmhamuuqortk', 'REFRESH: 2nd KK Assembly and Formation and Reorganization of Orgs para sa Kabataan ni San Francisco', 'This gathering aims to strengthen youth participation, leadership, and unity through the creation and reorganization of youth organizations. During the assembly, the financial report, accomplishment report, plans and activities for 2026, and fiesta activities will also be presented and discussed.\r\n\r\nNOTE: Please be reminded that attendance in this activity is one of the requirements to be official participants in the upcoming sports activities.', 'Published', '2025-10-11 01:24:11', '2025-10-11 01:00:00', '2025-10-11 17:00:00', 'SK Building, San Francisco, Iriga City', 50, '1762363451_9905d4265d56aa973555.jpg', 'active citizenship', 25, '2025-10-05 09:24:11', '2025-10-05 09:24:12', 0, NULL, 0, NULL, NULL, NULL),
(4, 16, 'trua8mnva523ll639ivjihpkao', 'Laro ng Salinhali 2025: The St. Francis Youth Games', 'The Sangguniang Kabataan of Barangay San Francisco proudly presents Laro ng Salinhali 2025: The St. Francis Youth Games! This two-day event invites all youth aged 15 to 30 from the barangay to showcase their skills, teamwork, and sportsmanship. Participants will compete in various events including Mobile Legends, Laro ng Lahi, Chess, Scrabble, and Rubik’s Cube. The activity aims to promote camaraderie, discipline, and cultural appreciation while fostering youth engagement through fun and meaningful competition.\r\nNote: ML and Laro ng Lahi must have 6 members per team.', 'Published', '2025-05-06 01:44:14', '2025-05-24 08:00:00', '2025-05-25 17:00:00', 'Zone 1, Basketball Court', 80, '1762364654_21fd47ecd1b20862f572.jpg', 'social inclusion and equity', 25, '2025-11-05 09:44:14', '2025-11-05 09:44:16', 0, NULL, 0, NULL, NULL, NULL),
(5, 36, 'sue9kqqld8f22r61oa0md66l0o', 'Tree Planting Activity: “Plant a Tree, Grow a Future”', 'As part of this year’s fiesta celebration, the Sangguniang Kabataan of Barangay San Juan proudly presents a Tree Planting Activity with the theme “Plant a Tree, Grow a Future.” This initiative aims to strengthen the community and promote environmental awareness by encouraging youth and residents to take part in tree planting efforts. Participants will gather at the Barangay Multi-Purpose Covered Court before proceeding to the planting site. Everyone is encouraged to join, wear comfortable clothing, bring water, and bring tools for planting. Let’s celebrate our fiesta by nurturing nature and building a greener future together!', 'Published', '2025-06-21 02:10:56', '2025-06-21 07:00:00', '2025-11-06 10:00:00', 'Zone 7, Bucao, San Juan, Iriga City ', 50, '1762366198_336197dddf9f238bd9a1.jpg', 'environment', 25, '2025-11-05 10:09:58', '2025-11-05 10:10:56', 0, NULL, 0, NULL, NULL, NULL),
(6, 16, '9soucc4v4rk2m5ptgv2plgpgr0', 'Final Oral Defense', 'Desciption', 'Published', '2025-11-06 16:54:20', '2025-11-06 16:51:00', '2025-11-08 16:51:00', 'CSPC', 200, '1762419260_9288240cc78860ac5bc9.jpg', 'others', 25, '2025-11-06 16:54:20', '2025-11-06 16:54:21', 0, NULL, 1, NULL, NULL, '[\"chairperson\"]'),
(14, 0, 'pkbk13b0cu8uq189hg1kakm6q0', 'Sangguniang Kabataan Barangay Christmas Celebration - TESTING ONLY', ' TESTING ONLY', 'Published', '2025-12-16 09:53:55', '2025-12-16 17:00:00', '2025-12-18 19:00:00', 'Iriga City Convention Center -  TESTING ONLY', 12, NULL, 'active citizenship', 25, '2025-12-16 09:40:10', '2025-12-16 09:45:06', 1, '2025-12-16 09:45:00', 1, NULL, NULL, '[\"all_pederasyon_officials\",\"pederasyon_officers\",\"pederasyon_members\"]');
